INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_050_M2_S1', 'regulatory authorities', '1', 'regulatory authorities: Public bodies empowered to administer, enforce, or oversee environmental laws and regulations. In Environmental Institutions and Regulatory Structure, the focus is on the analysis, design, implementation, interpretation, or evaluation of regulatory authorities within Environmental Law and Environmental Governance, particularly where the Environmental Institutions and Regulatory Structure module establishes its technical context.', 'SSD_COURSE_050_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M2_S2', 'delegated legislation', '2', 'delegated legislation: Legally authorised rules made by an administrative authority under powers granted by legislation. In Environmental Institutions and Regulatory Structure, the focus is on the analysis, design, implementation, interpretation, or evaluation of delegated legislation within Environmental Law and Environmental Governance, particularly where the Environmental Institutions and Regulatory Structure module establishes its technical context.', 'SSD_COURSE_050_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M2_S3', 'jurisdiction', '3', 'jurisdiction refers to the legal authority of a court, tribunal, or administrative body to hear and decide a matter. In Environmental Institutions and Regulatory Structure, the focus is on the analysis, design, implementation, interpretation, or evaluation of jurisdiction within Environmental Law and Environmental Governance, particularly where the Environmental Institutions and Regulatory Structure module establishes its technical context.', 'SSD_COURSE_050_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M2_S4', 'environmental governance', '4', 'environmental governance: environmental governance in Environmental Law and Environmental Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing environmental governance. In Environmental Institutions and Regulatory Structure, the focus is on the analysis, design, implementation, interpretation, or evaluation of environmental governance within Environmental Law and Environmental Governance, particularly where the Environmental Institutions and Regulatory Structure module establishes its technical context.', 'SSD_COURSE_050_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M3_S1', 'air pollution regulation', '1', 'air pollution regulation: Legal requirements governing the control, monitoring, permitting, and enforcement of emissions to protect air quality. In Pollution Control Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of air pollution regulation within Environmental Law and Environmental Governance, particularly where the Pollution Control Law module establishes its technical context.', 'SSD_COURSE_050_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M3_S2', 'water pollution regulation', '2', 'water pollution regulation: Legal requirements governing discharges and other activities that may contaminate water, including standards, permits, monitoring, and enforcement. In Pollution Control Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of water pollution regulation within Environmental Law and Environmental Governance, particularly where the Pollution Control Law module establishes its technical context.', 'SSD_COURSE_050_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M3_S3', 'waste regulation', '3', 'waste regulation: Legal requirements governing the generation, handling, transport, treatment, recovery, and disposal of waste. In Pollution Control Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of waste regulation within Environmental Law and Environmental Governance, particularly where the Pollution Control Law module establishes its technical context.', 'SSD_COURSE_050_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M3_S4', 'consent mechanisms', '4', 'consent mechanisms: Legal procedures through which authorities approve, condition, or refuse activities that may affect the environment. In Pollution Control Law, the focus is on the analysis, design, implementation, interpretation, or evaluation of consent mechanisms within Environmental Law and Environmental Governance, particularly where the Pollution Control Law module establishes its technical context.', 'SSD_COURSE_050_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M4_S1', 'strict liability', '1', 'strict liability: strict liability in Environmental Law and Environmental Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing strict liability. In Environmental Liability and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of strict liability within Environmental Law and Environmental Governance, particularly where the Environmental Liability and Enforcement module establishes its technical context.', 'SSD_COURSE_050_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M4_S2', 'environmental compensation', '2', 'environmental compensation: Financial or other legally required measures intended to address environmental damage or associated losses. In Environmental Liability and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of environmental compensation within Environmental Law and Environmental Governance, particularly where the Environmental Liability and Enforcement module establishes its technical context.', 'SSD_COURSE_050_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M4_S3', 'penalties', '3', 'penalties: Legal sanctions imposed for violations of environmental requirements. In Environmental Liability and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of penalties within Environmental Law and Environmental Governance, particularly where the Environmental Liability and Enforcement module establishes its technical context.', 'SSD_COURSE_050_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M4_S4', 'remediation', '4', 'remediation: Actions taken to contain, remove, restore, or otherwise address environmental contamination or damage. In Environmental Liability and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of remediation within Environmental Law and Environmental Governance, particularly where the Environmental Liability and Enforcement module establishes its technical context.', 'SSD_COURSE_050_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M4_S5', 'compliance', '5', 'compliance: compliance in Environmental Law and Environmental Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing compliance. In Environmental Liability and Enforcement, the focus is on the analysis, design, implementation, interpretation, or evaluation of compliance within Environmental Law and Environmental Governance, particularly where the Environmental Liability and Enforcement module establishes its technical context.', 'SSD_COURSE_050_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M5_S1', 'forests', '1', 'forests: Legal and governance frameworks governing protection, use, management, and conservation of forest resources. In Natural Resources and Environmental Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of forests within Environmental Law and Environmental Governance, particularly where the Natural Resources and Environmental Governance module establishes its technical context.', 'SSD_COURSE_050_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M5_S2', 'biodiversity', '2', 'biodiversity: Legal and institutional measures concerning conservation and sustainable use of biological diversity. In Natural Resources and Environmental Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of biodiversity within Environmental Law and Environmental Governance, particularly where the Natural Resources and Environmental Governance module establishes its technical context.', 'SSD_COURSE_050_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M5_S3', 'water resources', '3', 'water resources: Legal rules governing allocation, protection, use, pollution control, and management of water resources. In Natural Resources and Environmental Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of water resources within Environmental Law and Environmental Governance, particularly where the Natural Resources and Environmental Governance module establishes its technical context.', 'SSD_COURSE_050_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M5_S4', 'land use', '4', 'land use: Regulation of how land may be developed, occupied, conserved, or used in relation to environmental objectives. In Natural Resources and Environmental Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of land use within Environmental Law and Environmental Governance, particularly where the Natural Resources and Environmental Governance module establishes its technical context.', 'SSD_COURSE_050_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M5_S5', 'common resources', '5', 'common resources: Resources whose use and governance involve shared or collective interests rather than exclusive private ownership. In Natural Resources and Environmental Governance, the focus is on the analysis, design, implementation, interpretation, or evaluation of common resources within Environmental Law and Environmental Governance, particularly where the Natural Resources and Environmental Governance module establishes its technical context.', 'SSD_COURSE_050_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M6_S1', 'tribunals', '1', 'tribunals: Specialized adjudicatory bodies established under law to determine specified classes of disputes, claims, or regulatory matters within their statutory jurisdiction. In Environmental Adjudication and Remedies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_050_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M6_S2', 'judicial review', '2', 'judicial review: Judicial examination of the legality, jurisdiction, procedural propriety, and relevant legal constraints of decisions or actions by public authorities. In Environmental Adjudication and Remedies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_050_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M6_S3', 'writs', '3', 'writs: Judicial orders used to review or compel lawful exercise of public authority. In Environmental Adjudication and Remedies, the focus is on the analysis, design, implementation, interpretation, or evaluation of writs within Environmental Law and Environmental Governance, particularly where the Environmental Adjudication and Remedies module establishes its technical context.', 'SSD_COURSE_050_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M6_S4', 'injunctions', '4', 'injunctions: Court orders requiring a party to do or refrain from doing specified acts, generally used as a legal remedy where the requirements for injunctive relief are satisfied. In Environmental Adjudication and Remedies, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_050_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M6_S5', 'public interest litigation', '5', 'public interest litigation: Court proceedings brought to address matters affecting broader public or environmental interests. In Environmental Adjudication and Remedies, the focus is on the analysis, design, implementation, interpretation, or evaluation of public interest litigation within Environmental Law and Environmental Governance, particularly where the Environmental Adjudication and Remedies module establishes its technical context.', 'SSD_COURSE_050_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M7_S1', 'permits', '1', 'permits: Formal regulatory authorisations allowing specified activities subject to stated conditions. In Environmental Governance Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of permits within Environmental Law and Environmental Governance, particularly where the Environmental Governance Practice module establishes its technical context.', 'SSD_COURSE_050_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M7_S2', 'compliance systems', '2', 'compliance systems: compliance systems in Environmental Law and Environmental Governance concerns legal rules, institutional mechanisms, duties, procedures, and compliance considerations governing compliance systems. In Environmental Governance Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of compliance systems within Environmental Law and Environmental Governance, particularly where the Environmental Governance Practice module establishes its technical context.', 'SSD_COURSE_050_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M7_S3', 'monitoring', '3', 'monitoring: Systematic collection and review of observations or measurements over time to determine status, compliance, performance, or change against defined criteria. In Environmental Governance Practice, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_050_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M7_S4', 'reporting', '4', 'reporting: Structured communication of specified information, measurements, findings, or compliance information to an identified recipient under defined requirements. In Environmental Governance Practice, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_050_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_050_M7_S5', 'administrative decision-making', '5', 'administrative decision-making: Processes by which public authorities interpret rules, assess evidence, and make legally reviewable regulatory decisions. In Environmental Governance Practice, the focus is on the analysis, design, implementation, interpretation, or evaluation of administrative decision-making within Environmental Law and Environmental Governance, particularly where the Environmental Governance Practice module establishes its technical context.', 'SSD_COURSE_050_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M1_S1', 'statutory basis', '1', 'statutory basis refers to the legislation and delegated rules that establish the legal authority, scope, and procedures for environmental impact assessment. In EIA Legal Framework, the focus is on the analysis, design, implementation, interpretation, or evaluation of statutory basis within Environmental Impact Assessment Law, particularly where the EIA Legal Framework module establishes its technical context.', 'SSD_COURSE_051_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M1_S2', 'regulatory instruments', '2', 'regulatory instruments: Legal or administrative tools used to control activities, including standards, permits, approvals, conditions, reporting requirements, and enforcement mechanisms. In EIA Legal Framework, the focus is on the analysis, design, implementation, interpretation, or evaluation of regulatory instruments within Environmental Impact Assessment Law, particularly where the EIA Legal Framework module establishes its technical context.', 'SSD_COURSE_051_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M1_S3', 'project categories', '3', 'project categories: Legal or regulatory classes used to determine which projects require particular levels of environmental assessment or approval. In EIA Legal Framework, the focus is on the analysis, design, implementation, interpretation, or evaluation of project categories within Environmental Impact Assessment Law, particularly where the EIA Legal Framework module establishes its technical context.', 'SSD_COURSE_051_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M1_S4', 'competent authorities', '4', 'competent authorities: Public bodies legally responsible for screening, appraisal, approval, monitoring, or enforcement within an EIA system. In EIA Legal Framework, the focus is on the analysis, design, implementation, interpretation, or evaluation of competent authorities within Environmental Impact Assessment Law, particularly where the EIA Legal Framework module establishes its technical context.', 'SSD_COURSE_051_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M2_S1', 'screening', '1', 'screening refers to the legal or administrative process of deciding whether and at what level a proposed project requires environmental assessment. In Screening and Scoping, the focus is on the analysis, design, implementation, interpretation, or evaluation of screening within Environmental Impact Assessment Law, particularly where the Screening and Scoping module establishes its technical context.', 'SSD_COURSE_051_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M2_S2', 'terms of reference', '2', 'terms of reference: Requirements defining the issues, studies, alternatives, and information that an environmental assessment must address. In Screening and Scoping, the focus is on the analysis, design, implementation, interpretation, or evaluation of terms of reference within Environmental Impact Assessment Law, particularly where the Screening and Scoping module establishes its technical context.', 'SSD_COURSE_051_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M2_S3', 'baseline requirements', '3', 'baseline requirements: Legal expectations concerning the collection and documentation of existing environmental and social conditions. In Screening and Scoping, the focus is on the analysis, design, implementation, interpretation, or evaluation of baseline requirements within Environmental Impact Assessment Law, particularly where the Screening and Scoping module establishes its technical context.', 'SSD_COURSE_051_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M2_S4', 'alternatives', '4', 'alternatives: Different project locations, designs, technologies, scales, or operating approaches considered to avoid or reduce impacts. In Screening and Scoping, the focus is on the analysis, design, implementation, interpretation, or evaluation of alternatives within Environmental Impact Assessment Law, particularly where the Screening and Scoping module establishes its technical context.', 'SSD_COURSE_051_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M3_S1', 'impact prediction', '1', 'impact prediction: Assessment of likely environmental effects of a proposed project or alternative. In Impact Assessment and Environmental Appraisal, the focus is on the analysis, design, implementation, interpretation, or evaluation of impact prediction within Environmental Impact Assessment Law, particularly where the Impact Assessment and Environmental Appraisal module establishes its technical context.', 'SSD_COURSE_051_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M3_S2', 'cumulative impacts', '2', 'cumulative impacts: Combined environmental effects arising from a project together with other past, present, or reasonably foreseeable activities. In Impact Assessment and Environmental Appraisal, the focus is on the analysis, design, implementation, interpretation, or evaluation of cumulative impacts within Environmental Impact Assessment Law, particularly where the Impact Assessment and Environmental Appraisal module establishes its technical context.', 'SSD_COURSE_051_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M3_S3', 'risk', '3', 'risk refers to the likelihood and consequence of adverse environmental effects considered within regulatory assessment and decision-making. In Impact Assessment and Environmental Appraisal, the focus is on the analysis, design, implementation, interpretation, or evaluation of risk within Environmental Impact Assessment Law, particularly where the Impact Assessment and Environmental Appraisal module establishes its technical context.', 'SSD_COURSE_051_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M3_S4', 'mitigation hierarchy', '4', 'mitigation hierarchy refers to a sequence of avoiding, minimising, restoring, and, where applicable, compensating for environmental impacts. In Impact Assessment and Environmental Appraisal, the focus is on the analysis, design, implementation, interpretation, or evaluation of mitigation hierarchy within Environmental Impact Assessment Law, particularly where the Impact Assessment and Environmental Appraisal module establishes its technical context.', 'SSD_COURSE_051_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M4_S1', 'notice', '1', 'notice: Formal public or regulatory communication that initiates or informs a legally required EIA process. In Public Participation and Consultation, the focus is on the analysis, design, implementation, interpretation, or evaluation of notice within Environmental Impact Assessment Law, particularly where the Public Participation and Consultation module establishes its technical context.', 'SSD_COURSE_051_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M4_S2', 'disclosure', '2', 'disclosure: Provision or publication of specified information to persons or entities entitled or required to receive it under applicable rules or agreements. In Public Participation and Consultation, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_051_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M4_S3', 'hearings', '3', 'hearings: Formal opportunities for affected people or stakeholders to present views or evidence during environmental decision-making. In Public Participation and Consultation, the focus is on the analysis, design, implementation, interpretation, or evaluation of hearings within Environmental Impact Assessment Law, particularly where the Public Participation and Consultation module establishes its technical context.', 'SSD_COURSE_051_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M4_S4', 'submissions', '4', 'submissions: Written or other formal representations provided to an authority during an EIA or approval process. In Public Participation and Consultation, the focus is on the analysis, design, implementation, interpretation, or evaluation of submissions within Environmental Impact Assessment Law, particularly where the Public Participation and Consultation module establishes its technical context.', 'SSD_COURSE_051_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M4_S5', 'procedural fairness', '5', 'procedural fairness: Requirements that decision-making procedures provide appropriate notice, participation, impartiality, and consideration of relevant submissions. In Public Participation and Consultation, the focus is on the analysis, design, implementation, interpretation, or evaluation of procedural fairness within Environmental Impact Assessment Law, particularly where the Public Participation and Consultation module establishes its technical context.', 'SSD_COURSE_051_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M5_S1', 'appraisal committees', '1', 'appraisal committees: Expert or statutory bodies that review environmental assessment information and advise or decide on project approvals as authorised. In Environmental Decision-Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of appraisal committees within Environmental Impact Assessment Law, particularly where the Environmental Decision-Making module establishes its technical context.', 'SSD_COURSE_051_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M5_S2', 'conditions', '2', 'conditions: Specified requirements, limitations, obligations, or performance terms attached to a decision, approval, authorization, or agreement. In Environmental Decision-Making, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_051_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M5_S3', 'reasoned decisions', '3', 'reasoned decisions: Decisions that explain the relevant evidence, legal considerations, and reasons supporting the outcome. In Environmental Decision-Making, the focus is on the analysis, design, implementation, interpretation, or evaluation of reasoned decisions within Environmental Impact Assessment Law, particularly where the Environmental Decision-Making module establishes its technical context.', 'SSD_COURSE_051_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M5_S4', 'judicial review', '4', 'judicial review: Judicial examination of the legality, jurisdiction, procedural propriety, and relevant legal constraints of decisions or actions by public authorities. In Environmental Decision-Making, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_051_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_051_M6_S1', 'conditions', '1', 'conditions: Specified requirements, limitations, obligations, or performance terms attached to a decision, approval, authorization, or agreement. In Compliance and Post-Approval Monitoring, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_051_M6_S1', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;